// Compute the maximum value among the first `n` elements of `a`.
// Assumptions (per problem statement): 0 < n <= a.len() and n < 1000.
fn max(a: &Vec<i32>, n: usize) -> i32 {
    // Initialize with the first element in the prefix so the result
    // is guaranteed to come from within the first `n` positions.
    let mut m = a[0];

    // Scan only the first `n` elements; elements beyond that are ignored.
    for i in 1..n {
        if a[i] > m {
            m = a[i];
        }
    }

    m
}

fn main() {
    // Example usage
    let a = vec![3, 1, 7, 2, 9];
    let n = 4;
    let m = max(&a, n);
    println!("{m}"); // prints 7 (max of [3,1,7,2])
}